--LINKREFRESH DECLARE @COPYDOCNUM VARCHAR(30) = '{9}'; DECLARE @MFGNUM VARCHAR(30)='#MFGNUM#'; DECLARE @ROUOPE VARCHAR(30)='#ROUOPE#'; DECLARE @DOCNUM VARCHAR(30); DECLARE @ROUALT VARCHAR(30); DECLARE @CUSCOD VARCHAR(30); DECLARE @INTSPE VARCHAR(30); DECLARE @ITMNO VARCHAR(30);
SELECT @DOCNUM= CONCAT_WS('-',@MFGNUM,@ROUOPE); SELECT @ROUALT = H.ROUALT_0 , @ITMNO = H.ROUNUM_0 , @CUSCOD = I.BPCNUM_0 , @INTSPE = I.INTSPE_0 FROM #LC.X3DATA#MFGHEAD H INNER JOIN #LC.X3DATA#MFGITM I ON I.MFGNUM_0 = H.MFGNUM_0 AND I.ITMTYP_0 = 1 WHERE H.MFGNUM_0 = @MFGNUM;
INSERT INTO [QAINSPH] ([DOCNUM] ,[DOCDAT] ,[ROUTYP] ,[ROUCOD] ,[ITMNO] ,[MFGNUM] ,[ROUALT] ,[LOT] ,[TV] ,[ROUOPE] ,[CUSCOD] ,[INTSPEC] ,[HEATTITLE] ,[STA] ,[CLOSTA] ,[CLOUSR] ,[CLOTIM] ,[INSPINF] ,[DEMANDER] ,[INSPREA] ,[PROFILE] ,[CREUSR] ,[CRETIM]) SELECT @DOCNUM--<DOCNUM, varchar(30),> ,GETDATE()--<DOCDAT, date,> ,H.ROUTYP--<ROUTYP, varchar(30),> ,H.ROUCOD--<ROUCOD, varchar(30),> ,@ITMNO--<ITMNO, varchar(30),> ,@MFGNUM--<MFGNUM, varchar(30),> ,@ROUALT--<ROUALT, int,> ,H.LOT--<LOT, varchar(30),> ,H.TV --<TV, varchar(30),> ,@ROUOPE--<ROUOPE, varchar(30),> ,@CUSCOD--<CUSCOD, varchar(30),> ,@INTSPE--<INTSPEC, varchar(30),> ,H.HEATTITLE--<HEATTITLE, nvarchar(100),> ,H.STA--<STA, tinyint,> ,0--<CLOSTA, bit,> ,''--<CLOUSR, varchar(30),> ,NULL--<CLOTIM, datetime,> ,H.INSPINF--<INSPINF, nvarchar(500),> ,H.DEMANDER--<DEMANDER, varchar(30),> ,H.INSPREA--<INSPREA, nvarchar(100),> ,H.PROFILE--<PROFILE, nvarchar(200),> ,'#LOGIN_USER#'--<CREUSR, varchar(30),> ,GETDATE()--<CRETIM, datetime,> FROM QAINSPH H WHERE H.DOCNUM=@COPYDOCNUM;
INSERT INTO [QAINSPL] ([DOCNUM] ,[OPENUM] ,[OPESTD] ,[OPEGRP] ,[OPEUNT] ,[TRXUSER] ,[TRXDAT] ,[INSTCOD] ,[QTYOK] ,[QTYSC] ,[REASC] ,[CTLTYP] ,[MEAFRQ] ,[NMIN] ,[NNOR] ,[NMAX] ,[L1CHECK] ,[L2CHECK] ,[SAMAC_QTY] ,[SAMRE_QTY] ,[STA] ,[CREUSR] ,[CRETIM]) SELECT @DOCNUM--<DOCNUM, varchar(30),> ,L.OPENUM--<OPENUM, int,> ,L.OPESTD--<OPESTD, varchar(30),> ,L.OPEGRP--<OPEGRP, varchar(30),> ,L.OPEUNT--<OPEUNT, varchar(30),> ,L.TRXUSER--<TRXUSER, varchar(30),> ,L.TRXDAT--<TRXDAT, date,> ,L.INSTCOD--<INSTCOD, varchar(30),> ,L.QTYOK--<QTYOK, decimal(18,6),> ,L.QTYSC--<QTYSC, decimal(18,6),> ,L.REASC--<REASC, decimal(18,6),> ,L.CTLTYP--<CTLTYP, varchar(30),> ,L.MEAFRQ--<MEAFRQ, varchar(30),> ,L.NMIN--<NMIN, decimal(18,6),> ,L.NNOR--<NNOR, decimal(18,6),> ,L.NMAX--<NMAX, decimal(18,6),> ,L.L1CHECK--<L1CHECK, bit,> ,L.L2CHECK--<L2CHECK, bit,> ,L.SAMAC_QTY--<SAMAC_QTY, int,> ,L.SAMRE_QTY--<SAMRE_QTY, int,> ,L.STA--<STA, tinyint,> ,'#LOGIN_USER#'--<CREUSR, varchar(30),> ,GETDATE()--<CRETIM, datetime,> FROM QAINSPL L WHERE L.DOCNUM=@COPYDOCNUM;
INSERT INTO [QAINSPVAL] ([DOCNUM] ,[OPENUM] ,[VALLIN] ,[TRXLIN] ,[SPOOL] ,[COIL] ,[SAMP] ,[N1] ,[N2] ,[N3] ,[N4] ,[N5] ,[N6] ,[N7] ,[N8] ,[VALMIN] ,[VALAVG] ,[VALMAX] ,[L1] ,[L2] ,[STA] ,[NCTYP] ,[NCUSR] ,[NCTIM] ,[REMARK] ,[CREUSR] ,[CRETIM]) SELECT @DOCNUM ,V.[OPENUM] ,V.[VALLIN] ,V.[TRXLIN] ,V.[SPOOL] ,V.[COIL] ,V.[SAMP] ,V.[N1] ,V.[N2] ,V.[N3] ,V.[N4] ,V.[N5] ,V.[N6] ,V.[N7] ,V.[N8] ,V.[VALMIN] ,V.[VALAVG] ,V.[VALMAX] ,V.[L1] ,V.[L2] ,V.[STA] ,V.[NCTYP] ,V.[NCUSR] ,V.[NCTIM] ,V.[REMARK] ,'#LOGIN_USER#' ,GETDATE() FROM QAINSPVAL V WHERE V.DOCNUM=@COPYDOCNUM;
